import httpx
from fastapi import FastAPI, Form, File, UploadFile
from fastapi.testclient import TestClient

app = FastAPI()

@app.post("/upload")
async def upload(file_val: bytes = File(...), form_val: str = Form(...)):
    return {"form_val": form_val, "file_val": file_val.decode()}

client = TestClient(app)

def test_file_first():
    response = client.post(
        "/upload",
        files={"file_val": ("test.txt", "content")},
        data={"form_val": "value"},
    )
    print(f"Response: {response.status_code}, Body: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"form_val": "value", "file_val": "content"}

if __name__ == "__main__":
    test_file_first()
    print("Test passed!")
